//! Verification key parser for build.rs usage.
//!
//! Parses verification key JSON files (generated by snarkjs) and
//! converts them to Rust source code for the Groth16 verifier.
//!
//! # Example
//!
//! ```rust,ignore
//! use groth16_solana::vk::circom::generate_vk_file;
//! use groth16_solana::vk::setup::SetupKind;
//!
//! fn main() {
//!     generate_vk_file(
//!         "verification_key.json",
//!         "src",
//!         "verifying_key.rs",
//!         SetupKind::Production,
//!     ).unwrap();
//! }
//! ```

extern crate std;

use crate::groth16::Groth16Verifyingkey;
use crate::vk::setup::{self, SetupKind};
use alloc::format;
use alloc::string::String;
use alloc::vec::Vec;
use num_bigint::BigUint;
use serde::Deserialize;
use std::fs;
use std::path::Path;

/// Errors that can occur during verification key parsing
#[derive(Debug, thiserror::Error)]
pub enum VkParseError {
    #[error("Failed to read file: {0}")]
    IoError(#[from] std::io::Error),

    #[error("Failed to parse JSON: {0}")]
    JsonError(#[from] serde_json::Error),

    #[error("Invalid verification key data: {0}")]
    InvalidData(String),

    #[error(
        "vk_delta_2 equals vk_gamma_2: the setup had no phase-2 contribution, so anyone \
         can build a proof for any public inputs from the vk alone; declare it \
         SetupKind::InsecureTest if it is a test setup"
    )]
    ForgeableProductionVk,
}

/// Raw verification key data as it appears in JSON files
#[derive(Debug, Deserialize)]
struct RawVerifyingKey {
    #[serde(rename = "vk_alpha_1")]
    vk_alpha_1: Vec<String>,

    #[serde(rename = "vk_beta_2")]
    vk_beta_2: Vec<Vec<String>>,

    #[serde(rename = "vk_gamma_2")]
    vk_gamma_2: Vec<Vec<String>>,

    #[serde(rename = "vk_delta_2")]
    vk_delta_2: Vec<Vec<String>>,

    #[serde(rename = "IC")]
    ic: Vec<Vec<String>>,
}

/// Convert a bigint string to little-endian bytes, then reverse to big-endian
fn bigint_string_to_be_bytes(s: &str, size: usize) -> Result<Vec<u8>, VkParseError> {
    let bigint = s
        .parse::<BigUint>()
        .map_err(|e| VkParseError::InvalidData(format!("Failed to parse bigint '{}': {}", s, e)))?;

    let le_bytes = bigint.to_bytes_le();

    // Pad to desired size
    let mut padded = le_bytes;
    padded.resize(size, 0);

    // Reverse to get big-endian
    padded.reverse();
    Ok(padded)
}

/// Process G1 point: convert bigint to 32-byte BE
fn process_g1_component(component: &str) -> Result<Vec<u8>, VkParseError> {
    bigint_string_to_be_bytes(component, 32)
}

/// `bytes` as a fixed-size array; fails when a point in the JSON has
/// the wrong number of coordinates.
fn fixed_size<const N: usize>(bytes: &[u8], field_name: &str) -> Result<[u8; N], VkParseError> {
    bytes.try_into().map_err(|_| {
        VkParseError::InvalidData(format!(
            "{} encodes to {} bytes, expected {}",
            field_name,
            bytes.len(),
            N
        ))
    })
}

/// snarkjs stores points in projective form with a trailing z
/// component ("1" for G1, ["1", "0"] for G2); the generated const only
/// needs the affine part. Drops the trailing component, returning a
/// meaningful error (instead of an integer-underflow panic) when the
/// JSON field is an empty array.
fn affine_components<'a, T>(point: &'a [T], field_name: &str) -> Result<&'a [T], VkParseError> {
    point
        .split_last()
        .map(|(_z, affine)| affine)
        .ok_or_else(|| {
            VkParseError::InvalidData(format!(
                "{} is empty; expected projective point coordinates \
                 (affine components plus a trailing z component)",
                field_name
            ))
        })
}

/// Process G2 point: concatenate two 32-byte LE components, reverse the full 64 bytes, then split
fn process_g2_component(components: &[String]) -> Result<(Vec<u8>, Vec<u8>), VkParseError> {
    if components.len() != 2 {
        return Err(VkParseError::InvalidData(format!(
            "G2 component must have exactly 2 elements, got {}",
            components.len()
        )));
    }

    // Convert to LE bytes
    let c0_le = components[0]
        .parse::<BigUint>()
        .map_err(|e| VkParseError::InvalidData(format!("Failed to parse bigint: {}", e)))?
        .to_bytes_le();
    let c1_le = components[1]
        .parse::<BigUint>()
        .map_err(|e| VkParseError::InvalidData(format!("Failed to parse bigint: {}", e)))?
        .to_bytes_le();

    // Pad to 32 bytes
    let mut c0_padded = c0_le;
    c0_padded.resize(32, 0);
    let mut c1_padded = c1_le;
    c1_padded.resize(32, 0);

    // Concatenate and reverse
    let mut concat = Vec::new();
    concat.extend_from_slice(&c0_padded);
    concat.extend_from_slice(&c1_padded);
    concat.reverse();

    // Split back
    let part0 = concat[0..32].to_vec();
    let part1 = concat[32..64].to_vec();

    Ok((part0, part1))
}

/// Parse verification key JSON and generate Rust source code as a String
///
/// # Arguments
///
/// * `json_content` - The JSON content as a string
/// * `setup` - Where the setup randomness came from
///
/// # Returns
///
/// A String containing the generated Rust code defining a `Groth16Verifyingkey` constant
/// and the `VERIFYINGKEY_VK_SHA256` / `VERIFYINGKEY_INSECURE_TEST_SETUP`
/// consts (see [`crate::vk::setup`]). Fails with
/// [`VkParseError::ForgeableProductionVk`] when `setup` is
/// [`SetupKind::Production`] but delta equals gamma.
pub fn parse_vk_json_to_rust_string(
    json_content: &str,
    setup: SetupKind,
) -> Result<String, VkParseError> {
    let raw_vk: RawVerifyingKey = serde_json::from_str(json_content)?;

    let mut output = String::new();

    // Header. `IC` has one entry per public input plus the constant
    // K[0] term, so it must never be empty.
    let nr_pubinputs = raw_vk.ic.len().checked_sub(1).ok_or_else(|| {
        VkParseError::InvalidData(String::from(
            "IC is empty; expected at least the constant K[0] term",
        ))
    })?;
    output.push_str("// This file is generated by groth16_solana::vk::circom.\n");
    output.push_str("// Do not edit by hand.\n\n");
    output.push_str(setup::header_warning(setup));
    output.push_str("use groth16_solana::groth16::Groth16Verifyingkey;\n\n");
    // `rustfmt::skip` keeps `cargo fmt --check` off the generated
    // const, whose layout is whatever this generator emits.
    output.push_str("#[rustfmt::skip]\n");
    output.push_str(&format!(
        "pub const VERIFYINGKEY: Groth16Verifyingkey = Groth16Verifyingkey {{\n\tnr_pubinputs: {},\n\n",
        nr_pubinputs
    ));

    // Process vk_alpha_g1 - flat [u8; 64]
    output.push_str("\tvk_alpha_g1: [");
    let mut alpha_bytes = Vec::new();
    for component in affine_components(&raw_vk.vk_alpha_1, "vk_alpha_1")? {
        let bytes = process_g1_component(component)?;
        alpha_bytes.extend_from_slice(&bytes);
    }
    output.push_str(&setup::byte_list(&alpha_bytes));
    output.push_str("],\n\n");

    // Process vk_beta_g2 - flat [u8; 128]
    output.push_str("\tvk_beta_g2: [");
    let mut beta_bytes = Vec::new();
    for pair in affine_components(&raw_vk.vk_beta_2, "vk_beta_2")? {
        let (part0, part1) = process_g2_component(pair)?;
        beta_bytes.extend_from_slice(&part0);
        beta_bytes.extend_from_slice(&part1);
    }
    output.push_str(&setup::byte_list(&beta_bytes));
    output.push_str("],\n\n");

    // Process vk_gamma_g2 - flat [u8; 128]
    output.push_str("\tvk_gamma_g2: [");
    let mut gamma_bytes = Vec::new();
    for pair in affine_components(&raw_vk.vk_gamma_2, "vk_gamma_2")? {
        let (part0, part1) = process_g2_component(pair)?;
        gamma_bytes.extend_from_slice(&part0);
        gamma_bytes.extend_from_slice(&part1);
    }
    output.push_str(&setup::byte_list(&gamma_bytes));
    output.push_str("],\n\n");

    // Process vk_delta_g2 - flat [u8; 128]
    output.push_str("\tvk_delta_g2: [");
    let mut delta_bytes = Vec::new();
    for pair in affine_components(&raw_vk.vk_delta_2, "vk_delta_2")? {
        let (part0, part1) = process_g2_component(pair)?;
        delta_bytes.extend_from_slice(&part0);
        delta_bytes.extend_from_slice(&part1);
    }
    if setup == SetupKind::Production && setup::delta_equals_gamma(&gamma_bytes, &delta_bytes) {
        return Err(VkParseError::ForgeableProductionVk);
    }
    output.push_str(&setup::byte_list(&delta_bytes));
    output.push_str("],\n\n");

    // Process vk_ic - &[[u8; 64]]
    output.push_str("\tvk_ic: &[\n");
    let mut ic = Vec::with_capacity(raw_vk.ic.len());
    for (point_index, point) in raw_vk.ic.iter().enumerate() {
        let label = format!("IC[{}]", point_index);
        let mut point_bytes = Vec::new();
        for component in affine_components(point, &label)? {
            point_bytes.extend_from_slice(&process_g1_component(component)?);
        }
        output.push_str(&format!("\t\t[{}],\n", setup::byte_list(&point_bytes)));
        ic.push(fixed_size(&point_bytes, &label)?);
    }
    output.push_str("\t],\n\n");

    // snarkjs/circom verifying keys have no BSB22 commitment key.
    output.push_str("\tvk_commitment: None,\n");

    output.push_str("};\n");
    let vk = Groth16Verifyingkey {
        nr_pubinputs,
        vk_alpha_g1: fixed_size(&alpha_bytes, "vk_alpha_1")?,
        vk_beta_g2: fixed_size(&beta_bytes, "vk_beta_2")?,
        vk_gamma_g2: fixed_size(&gamma_bytes, "vk_gamma_2")?,
        vk_delta_g2: fixed_size(&delta_bytes, "vk_delta_2")?,
        vk_ic: &ic,
        vk_commitment: None,
    };
    let metadata =
        setup::metadata_rust_source(&output, "VERIFYINGKEY", setup, &setup::vk_sha256(&vk));
    output.push_str(&metadata);

    Ok(output)
}

/// Generate a verification key Rust file from a JSON file
///
/// This is a convenience wrapper that reads the JSON file, parses it,
/// and writes the generated Rust code to the specified output location.
///
/// # Arguments
///
/// * `json_path` - Path to the input JSON file containing the verification key
/// * `output_dir` - Directory where the output Rust file will be written
/// * `output_filename` - Name of the output Rust file (e.g., "verifying_key.rs")
/// * `setup` - Where the setup randomness came from; an
///   [`SetupKind::InsecureTest`] vk compiles only in a crate that
///   enables an `insecure-test-setup` feature
///
/// # Example
///
/// ```rust,ignore
/// // In build.rs
/// use groth16_solana::vk::circom::generate_vk_file;
/// use groth16_solana::vk::setup::SetupKind;
///
/// fn main() {
///     generate_vk_file(
///         "verification_key.json",
///         "src",
///         "verifying_key.rs",
///         SetupKind::Production,
///     ).unwrap();
/// }
/// ```
pub fn generate_vk_file(
    json_path: impl AsRef<Path>,
    output_dir: impl AsRef<Path>,
    output_filename: &str,
    setup: SetupKind,
) -> Result<(), VkParseError> {
    // Read JSON file
    let json_content = fs::read_to_string(json_path.as_ref())?;

    // Parse and generate Rust code
    let rust_code = parse_vk_json_to_rust_string(&json_content, setup)?;

    // Create output directory if it doesn't exist
    fs::create_dir_all(output_dir.as_ref())?;

    // Write output file
    let output_path = output_dir.as_ref().join(output_filename);
    fs::write(output_path, rust_code)?;

    Ok(())
}
